// Minimal stub of @minecraft/server, enough to evaluate the pack and fire events.
export const subscriptions = { before: {}, after: {}, systemBefore: {} };
export const intervals = [];
export const commands = [];
const props = new Map();

function bus(store) {
  return new Proxy({}, {
    get(_t, name) {
      return { subscribe: (fn) => { (store[name] ||= []).push(fn); return fn; } };
    }
  });
}

export const world = {
  beforeEvents: bus(subscriptions.before),
  afterEvents: bus(subscriptions.after),
  getPlayers: () => [],
  getDimension: () => dimensionStub,
  getDynamicProperty: (k) => props.get(k),
  setDynamicProperty: (k, v) => { v === undefined ? props.delete(k) : props.set(k, v); },
  getDynamicPropertyIds: () => [...props.keys()],
};

export const system = {
  beforeEvents: bus(subscriptions.systemBefore),
  run: (fn) => { fn(); return 1; },
  runTimeout: (fn) => { intervals.push({ kind: "timeout", fn }); return intervals.length; },
  runInterval: (fn, t) => { intervals.push({ kind: "interval", fn, t }); return intervals.length; },
  clearRun: () => {},
};

export const CommandPermissionLevel = { Any: 0, GameDirectors: 1, Admin: 2, Owner: 3 };
export class ItemStack { constructor(typeId, amount = 1) { this.typeId = typeId; this.amount = amount; } }

const dimensionStub = {
  id: "minecraft:overworld",
  getBlock: () => undefined,
  getPlayers: () => [],
  getEntities: () => [],
  spawnItem: () => {},
  spawnParticle: () => {},
  playSound: () => {},
};
export { dimensionStub };
